// When the app is launched without that flag (e.g. Android Studio's Run ▶
// button), it falls back to the git-ignored asset assets/secrets/gemini.key,
// loaded once at startup by bootstrap().
const String _apiKey = String.fromEnvironment('GEMINI_API_KEY');

const String _model = String.fromEnvironment(
  'ASKIMAN_MODEL',
  defaultValue: 'gemini-3.6-flash',
);

const String _genBase =
    'https://generativelanguage.googleapis.com/v1beta/models';

const int kDayLimit = 30; // soft per-device quota
const int kMinuteLimit = 5;

const double _arMinScore = 0.58; // broad recall sweep
const double _latinMinScore = 0.62;

// Strict acceptance: a verified verdict is ONLY emitted when the top corpus
// hit clears these bars AND clearly dominates the runner-up (no ties → no
// "first match wins" guesses for common fragments).
const double _arStrictScore = 0.92;
const double _arStrictContainment = 0.85;
const double _arStrictGap = 0.08;
const double _latinStrictScore = 0.75;
const double _latinStrictContainment = 0.70;
const double _latinStrictGap = 0.10;

// Medium band: below strict but with a plausible shortlist → grounded
// adjudicator call may confirm a paraphrase/translation.
const double _arAdjudicateMin = 0.60;
const double _latinAdjudicateMin = 0.50;

// OCR-relaxed bars: when the source is a camera/gallery PHOTO the text was read
// by OCR, which always introduces spelling/line-break noise. The strict corpus
// bars would reject valid ayahs/hadiths, so the photo path verifies with the
// relaxed thresholds below AND routes more borderline cases to the Gemini
// adjudicator (which quotes the correct corpus text — never the garbled OCR).
const double _ocrArStrictScore = 0.80;
const double _ocrArStrictContainment = 0.75;
const double _ocrArAdjudicateMin = 0.50;
const double _ocrLatinStrictScore = 0.65;
const double _ocrLatinStrictContainment = 0.60;
const double _ocrLatinAdjudicateMin = 0.40;

